import { isCi } from "./env.js";
import { log } from "./log.js";
import { codeFromBody } from "./api.js";
import open from "open";
import prompts from "prompts";
//#region src/sso_recovery.ts
/**
* Extract the SSO step-up URL from the error message.
*
* The Neon public API carries the recovery URL in the human-readable `message`
* ("...Open <url> in your browser to authorize, then retry."), not a structured field — so this
* works against the API's standard error shape without a bespoke contract.
*/
function extractStepUpUrl(message) {
	if (typeof message !== "string") return;
	const match = message.match(/(https?:\/\/[^\s)]+)/);
	return match ? match[1] : void 0;
}
/**
* Whether the invocation opted out of prompts via --yes/-y.
*
* The skip-prompts flag is per-command in this CLI (link, projects update, init, …), not a global
* option, so — exactly like the --help/-h check in the error handler — detect it from argv rather than
* a parsed global. A run that documented itself as non-interactive (`neon link -y`) must take the
* unattended path, never open a browser or block on a confirm.
*/
function promptsSkipped() {
	return process.argv.includes("--yes") || process.argv.includes("-y");
}
/** Whether this process can drive an interactive open-browser-then-confirm-and-retry flow. */
function canInteract() {
	return !isCi() && !promptsSkipped() && Boolean(process.stdout.isTTY) && Boolean(process.stdin.isTTY);
}
/**
* Recover from an SSO authorization error.
*
* Detection is by the machine `code` in the response body, NOT the HTTP status: Neon masks org
* access-denials as 404 (existence-hiding), so the error arrives as 403 or 404 with the code in the
* body.
*   - SSO_AUTHORIZATION_REQUIRED: the user must complete a one-time SSO authorization in a browser.
*     On an interactive terminal we open the step-up URL and wait for the user to confirm they've
*     finished before signalling a retry. Unattended (CI, no TTY, or an explicit --yes/-y that opted
*     out of prompts) we print the URL and fail, since no browser round-trip is possible.
*   - SSO_ORG_CREDS_ONLY: terminal — no browser step resolves it; the user must use an
*     organization-scoped API key. Return false (no retry).
*
* @param error   the API error
* @param canRetry whether the caller is willing to retry (false once we've already retried)
* @returns true if the caller should retry the command, false otherwise
*/
const recoverFromSSO = async (error, canRetry) => {
	const code = codeFromBody(error.data);
	if (code === "SSO_ORG_CREDS_ONLY") {
		log.error(error.message);
		return false;
	}
	if (code !== "SSO_AUTHORIZATION_REQUIRED") return false;
	if (!canRetry) {
		log.error(error.message);
		return false;
	}
	const stepUpUrl = extractStepUpUrl(error.message);
	if (!stepUpUrl) {
		log.error(error.message);
		return false;
	}
	if (!canInteract()) {
		log.error("This organization requires a one-time SSO authorization, which needs an interactive browser session. Open this URL in a browser to authorize, then re-run the command:\n" + stepUpUrl);
		return false;
	}
	log.info(`This organization requires SSO authorization. Opening your browser to authorize; if it doesn't open, visit this URL manually:\n${stepUpUrl}`);
	try {
		(await open(stepUpUrl)).once("error", (err) => {
			log.warning(`Could not launch a browser automatically: ${err.message}`);
		});
	} catch {
		log.warning("Could not launch a browser automatically; open the URL above manually.");
	}
	const { confirmed } = await prompts({
		type: "confirm",
		name: "confirmed",
		message: "Press Enter once you've completed authorization in the browser to retry (or 'n' to cancel)",
		initial: true
	});
	if (confirmed !== true) {
		log.error(`SSO authorization was not completed. Re-run the command after authorizing at:\n${stepUpUrl}`);
		return false;
	}
	return true;
};
//#endregion
export { recoverFromSSO };
